"use strict";

// Names currently held, in memory. `take` hands its callback the function
// that gives the name back; that function takes a callback too.
const taken = new Set();
const failing = new Set();

function take(name, options, done) {
  if (taken.has(name)) {
    done(new Error("Already held"));
    return;
  }
  taken.add(name);
  if (options && options.failRelease) failing.add(name);
  done(null, (released) => {
    taken.delete(name);
    if (failing.delete(name)) released(new Error("Release failed for " + name));
    else released(null, "released " + name);
  });
}

function isTaken(name, done) {
  done(null, taken.has(name));
}

module.exports = { take, isTaken };
